const K11_SOURCE = 'target/ERB/口上/EVENT_K11_リリィ.ERB';

function exact_line(ref, line) {
  const escaped = line.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return {
    src: K11_SOURCE,
    ref,
    any: [new RegExp(`^\\s*${escaped}\\s*$`, 'm')],
  };
}

